#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A is an N x N matrix: i = row index, j = column index
	// j is the innermost dimension to match C row-major A[i][j]
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;


/* Array initialization. */
void init_array(auto A_ij) {
	// A_ij: i x j
	using namespace noarr;

	std::size_t n = A_ij | get_length<'i'>();

	// First: build a lower-triangular matrix with ones on the diagonal
	traverser(A_ij).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		std::size_t i = get_index<'i'>(state_i);

		// j from 0 to i (inclusive)
		trav_i
			.order(slice<'j'>(0, i + 1))
			.for_each([=](auto state_ij) {
				auto j = get_index<'j'>(state_ij);
				// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
				auto neg_j_mod_n = static_cast<long long>(-static_cast<long long>(j) % static_cast<long long>(n));
				A_ij[state_ij] = static_cast<num_t>(neg_j_mod_n) / static_cast<num_t>(n) + static_cast<num_t>(1);
			});

		// j from i+1 to n-1
		if (i + 1 < n) {
			trav_i
				.order(slice<'j'>(i + 1, n - (i + 1)))
				.for_each([=](auto state_ij) {
					A_ij[state_ij] = static_cast<num_t>(0);
				});
		}

		// A[i][i] = 1;
		A_ij[idx<'i', 'j'>(i, i)] = static_cast<num_t>(1);
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = sum_t A[r][t] * A[s][t], then A = B.

	auto lengths = set_length<'i'>(n) ^ set_length<'j'>(n);

	// B has the same layout as A
	auto B_ij = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ lengths);

	// Initialize B to zero
	traverser(B_ij).for_each([=](auto state) {
		B_ij[state] = static_cast<num_t>(0);
	});

	// Views of A for the multiplication:
	// A_ik: dims {i, k}  (column dim renamed from j -> k)
	// A_jk: dims {j, k}  (row dim renamed i -> j, col dim j -> k)
	auto A_ik = A_ij ^ rename<'j', 'k'>();
	auto A_jk = A_ij ^ rename<'i', 'j', 'j', 'k'>();

	// B[i][j] += A[i][k] * A[j][k]
	traverser(B_ij, A_ik, A_jk).template for_dims<'k'>([=](auto trav_k) {
		trav_k.for_each([=](auto state) {
			B_ij[state] += A_ik[state] * A_jk[state];
		});
	});

	// Copy B back into A
	traverser(A_ij, B_ij).for_each([=](auto state) {
		A_ij[state] = B_ij[state];
	});
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
