void kernel_lu(auto A_ij) {
	// A_ij: i x j
	using namespace noarr;

	// Views of A for the LU factorization:
	// A_ik: dims {i, k} (column index renamed from j -> k)
	// A_kj: dims {k, j} (row index renamed from i -> k)
	auto A_ik = A_ij ^ rename<'j', 'k'>();
	auto A_kj = A_ij ^ rename<'i', 'k'>();

	std::size_t n = A_ij | get_length<'i'>();

	// Original C code:
	// for (i = 0; i < N; i++) {
	//   for (j = 0; j < i; j++) {
	//     for (k = 0; k < j; k++)
	//       A[i][j] -= A[i][k] * A[k][j];
	//     A[i][j] /= A[j][j];
	//   }
	//   for (j = i; j < N; j++) {
	//     for (k = 0; k < i; k++)
	//       A[i][j] -= A[i][k] * A[k][j];
	//   }
	// }

#pragma scop
	traverser(A_ij, A_ik, A_kj).template for_dims<'i'>([=](auto trav_i) {
		auto state_i = trav_i.state();
		std::size_t i = get_index<'i'>(state_i);

		// First j-loop: 0 <= j < i
		trav_i
			.order(slice<'j'>(0, i))
			.template for_dims<'j'>([=](auto trav_ij) {
				auto state_ij = trav_ij.state();
				std::size_t j = get_index<'j'>(state_ij);

				// Inner k-loop: 0 <= k < j
				trav_ij
					.order(slice<'k'>(0, j))
					.for_each([=](auto state_ijk) {
						// A[i][j] -= A[i][k] * A[k][j];
						A_ij[state_ijk] -= A_ik[state_ijk] * A_kj[state_ijk];
					});

				// A[i][j] /= A[j][j];
				A_ij[state_ij] /= A_ij[idx<'i', 'j'>(j, j)];
			});

		// Second j-loop: i <= j < n
		trav_i
			.order(slice<'j'>(i, n - i))
			.template for_dims<'j'>([=](auto trav_ij) {
				auto state_ij = trav_ij.state();
				std::size_t j = get_index<'j'>(state_ij);

				// Inner k-loop: 0 <= k < i
				trav_ij
					.order(slice<'k'>(0, i))
					.for_each([=](auto state_ijk) {
						// A[i][j] -= A[i][k] * A[k][j];
						A_ij[state_ijk] -= A_ik[state_ijk] * A_kj[state_ijk];
					});
			});
	});
#pragma endscop
}

