// Array initialization
void init_array(auto A) {
	using namespace noarr;

	// Matrix size (N)
	auto n = A | get_length<'i'>();

	// First, initialize A to the lower-triangular pattern used by PolyBench
	traverser(A).template for_dims<'i'>([=](auto trav_i) {
		auto s_i = trav_i.state();
		auto i = get_index<'i'>(s_i);

		// j from 0..n-1; we branch to emulate the original two loops
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			auto s_ij = trav_ij.state();
			auto j = get_index<'j'>(s_ij);

			if (j <= i) {
				// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
				// Carefully reproduce C integer semantics
				int jj = static_cast<int>(j);
				int nn = static_cast<int>(n);
				num_t val = static_cast<num_t>((-jj % nn)) / static_cast<num_t>(nn) + static_cast<num_t>(1);
				A[s_ij] = val;
			} else { // j > i
				A[s_ij] = static_cast<num_t>(0);
			}
		});

		// A[i][i] = 1;
		A[noarr::idx<'i', 'j'>(i, i)] = static_cast<num_t>(1);
	});

	// Make the matrix positive semi-definite (same as in Cholesky benchmark)
	// B is a temporary N x N matrix
	auto B = noarr::bag(A.structure());

	// B[r][s] = 0
	traverser(B).for_each([=](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// B[r][s] += A[r][t] * A[s][t]
	// Original order: for t, for r, for s
	for (std::size_t t = 0; t < n; ++t) {
		traverser(B).for_each([=](auto state) {
			auto [r, s] = get_indices<'i', 'j'>(state);
			num_t art = A[noarr::idx<'i', 'j'>(r, t)];
			num_t ast = A[noarr::idx<'i', 'j'>(s, t)];
			B[state] += art * ast;
		});
	}

	// Copy B back into A: A[r][s] = B[r][s]
	traverser(A, B).for_each([=](auto state) {
		A[state] = B[state];
	});
}

// Main computational kernel: in-place LU decomposition of A
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	using namespace noarr;

	// Views of A to expose a third logical dimension 'k' for the inner products:
	// Aik[i, k] = A[i, k]
	auto Aik = A.get_ref() ^ noarr::rename<'j', 'k'>();
	// Akj[k, j] = A[k, j]
	auto Akj = A.get_ref() ^ noarr::rename<'i', 'k'>();

	#pragma scop
	// Outer loop over i
	traverser(A, Aik, Akj).template for_dims<'i'>([=](auto trav_i) {
		auto s_i = trav_i.state();
		auto i = get_index<'i'>(s_i);

		// First part: for (j = 0; j < i; j++)
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			auto s_ij = trav_ij.state();
			auto j = get_index<'j'>(s_ij);

			if (j < i) {
				// A[i][j] -= sum_{k=0}^{j-1} A[i][k] * A[k][j]
				trav_ij.template for_each<'k'>([=](auto s_ijk) {
					auto k = get_index<'k'>(s_ijk);
					if (k < j) {
						// A uses dims (i, j) and ignores k
						// Aik uses (i, k), Akj uses (k, j)
						A[s_ijk] -= Aik[s_ijk] * Akj[s_ijk];
					}
				});

				// A[i][j] /= A[j][j];
				A[s_ij] /= A[noarr::idx<'i', 'j'>(j, j)];
			}
		});

		// Second part: for (j = i; j < N; j++)
		trav_i.template for_dims<'j'>([=](auto trav_ij) {
			auto s_ij = trav_ij.state();
			auto j = get_index<'j'>(s_ij);

			if (j >= i) {
				// A[i][j] -= sum_{k=0}^{i-1} A[i][k] * A[k][j]
				trav_ij.template for_each<'k'>([=](auto s_ijk) {
					auto k = get_index<'k'>(s_ijk);
					if (k < i) {
						A[s_ijk] -= Aik[s_ijk] * Akj[s_ijk];
					}
				});
			}
		});
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Problem size
	std::size_t n = N;

	// Structure: A is N x N
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// Initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// Optionally print result (one number per line)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// Print execution time (seconds)
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}

#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
void init_array(auto A) {
	// A: i x j
	using namespace noarr;

	auto n = A | get_length<'i'>(); // matrix is n x n

	// Initialize A as unit-lower plus some values below diagonal, 0 above
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	auto B = noarr::bag(A.structure());

	// Zero B
	traverser(B).for_each([&](auto state) {
		B[state] = static_cast<num_t>(0);
	});

	// Outer loop over t
	traverser(t_structure)
		.order(noarr::set_length<'t'>(n))
		.for_each([&](auto t_state) {
			auto t = get_index<'t'>(t_state);

			// Inner loops over r, s (i, j)
			traverser(B).for_each([&](auto rs_state) {
				auto [r, s] = get_indices<'i', 'j'>(rs_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				B[rs_state] += A[rt_state] * A[st_state];
			});
		});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// First inner loop: 0 <= j < i
		if (i_idx > 0) {
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// for (k = 0; k < j; k++)
				if (j_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							A[ij_state] -= A[ik_state] * A[kj_state];
						});
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				A[ij_state] /= A[jj_state];
			});
		}

		// Second inner loop: i <= j < n
		auto len_second = n - i_idx;
		if (len_second > 0) {
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

			trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// for (k = 0; k < i; k++)
				if (i_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(i_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							A[ij_state] -= A[ik_state] * A[kj_state];
						});
				}
			});
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
